-- =============================================================================
-- CEIBO AI - Supabase Seed Data
-- =============================================================================
-- Realistic multi-tenant seed data for Ceibo AI Tech Solutions (Tenant A)
-- and Rival Retail Corp (Tenant B), with 30 days of WhatsApp chat analytics.
-- =============================================================================

-- 1. Insert Empresas (Tenants)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    slug = EXCLUDED.slug,
    plan = EXCLUDED.plan;

-- 2. Insert Perfiles (User Profiles mapped to Auth users)
ON CONFLICT (id) DO UPDATE SET
    empresa_id = EXCLUDED.empresa_id,
    full_name = EXCLUDED.full_name,
    role = EXCLUDED.role,
    email = EXCLUDED.email;

-- 3. Insert 30 Days of Chat Analytics for Tenant A (Ceibo AI Tech Solutions)
ON CONFLICT (empresa_id, date) DO UPDATE SET
    resueltas_ia = EXCLUDED.resueltas_ia,
    derivadas_humano = EXCLUDED.derivadas_humano,
    total_consultas = EXCLUDED.total_consultas,
    horas_ahorradas = EXCLUDED.horas_ahorradas;
